mapper.select:
select
    t1.*,
    t2.id_card_name,
    t3.hedged_flag
from binance_trade_info t1
left join binance_account_info t2 on t2.uid = t1.uid
left join binance_trade_info_ext t3 on t3.order_id = t1.order_id
where t1.time > '2025-01-01'



                and (t3.hedged_flag = 0 or t3.hedged_flag IS NULL)


                and t3.hedged_flag = #{criteria.hedgedFlag}




        and t1.symbol = #{criteria.symbol}


        and t1.order_id = #{criteria.orderId}


        and t1.commission_asset = #{criteria.commissionAsset}


        and t1.is_buyer = #{criteria.isBuyer}


        and t1.is_maker = #{criteria.isMaker}


        and t1.is_best_match = #{criteria.isBestMatch}


        and t1.uid = #{criteria.uid}


        AND t1.price BETWEEN #{criteria.price[0]} AND #{criteria.price[1]}


        AND t1.qty BETWEEN #{criteria.qty[0]} AND #{criteria.qty[1]}


        AND t1.commission BETWEEN #{criteria.commission[0]} AND #{criteria.commission[1]}


        AND t1.time BETWEEN #{criteria.time[0]} AND #{criteria.time[1]}


        AND t1.quote_qty BETWEEN #{criteria.quoteQty[0]} AND #{criteria.quoteQty[1]}


    ORDER BY t1.${criteria.orderColumn} ${criteria.orderDirection}
